const checksum = (ring) => ring.reduce((s, [x, y]) => s + x * 7 + y * 13, 0);

/** Apply `koreaShapeFixes` (runs after the China fixes; throws if a target is missing or changed). */
export function applyKoreaShapeFixes(entities) {
  const { _hold: hold = {}, ...trims } = KR_TRIMS;
  const qing = entities.find((x) => x.id === 'qing-china');
  const q1682 = qing?.overlays.find((o) => o.year === 1682)?.regions.find((r) => r.id === 'manchuria');
  const kf1750 = qing?.overlays.find((o) => o.year === 1750);
  const r1750 = kf1750?.regions.find((r) => r.id === 'manchuria');
  const want = hold['qing-china|manchuria|1750'];
  if (want !== undefined) {
    if (!q1682 || !r1750 || Math.abs(checksum(r1750.ring) - want) > 1e-6 || qing.overlays.some((o) => o.year === 1814)) throw new Error('south korea fixes: qing-china manchuria 1750 changed — regenerate');
    kf1750.regions = kf1750.regions.map((r) => (r === r1750 ? { ...r1750, ring: q1682.ring.map((p) => [...p]) } : r));
    qing.overlays.push({ ...kf1750, year: 1814, regions: kf1750.regions.map((r) => ({ ...r, ring: r.ring.map((p) => [...p]) })) });
    qing.overlays.sort((a, b) => a.year - b.year);
  }
  for (const [id, regions] of Object.entries(trims)) {
    const ent = entities.find((x) => x.id === id);
    if (!ent) throw new Error(`south korea fixes: no entity ${id}`);
    for (const [region, rings] of Object.entries(regions)) {
      for (const [y, { sum, ring }] of Object.entries(rings)) {
        const kf = ent.overlays.find((o) => o.year === Number(y));
        const r = kf?.regions.find((q) => typeof q !== 'string' && q.id === region);
        if (!r?.ring || Math.abs(checksum(r.ring) - sum) > 1e-6) throw new Error(`south korea fixes: ${id} ${region} ${y} changed — regenerate the trim`);
        // keyframes can share a region object: replace it with a trimmed copy for this keyframe only
        if (ring) kf.regions = kf.regions.map((q) => (q === r ? { ...r, ring: ensureClockwise(ring) } : q));
        else kf.regions = kf.regions.filter((q) => q !== r);
      }
    }
  }
}

